test('starts with initial stack', () => {
  const { result } = renderHook(() => useStack([1, 2]));
  expect(result.current.stack).toEqual([1, 2]);
});

test('push adds to top (end of array)', () => {
  const { result } = renderHook(() => useStack([]));
  act(() => result.current.push('a'));
  act(() => result.current.push('b'));
  expect(result.current.stack).toEqual(['a', 'b']);
});

test('pop removes top item', () => {
  const { result } = renderHook(() => useStack(['a', 'b', 'c']));
  act(() => result.current.pop());
  expect(result.current.stack).toEqual(['a', 'b']);
});

test('peek reads top item without removing', () => {
  const { result } = renderHook(() => useStack(['x', 'y']));
  expect(result.current.peek).toBe('y');
  expect(result.current.stack.length).toBe(2);
});

