solution:
import { useState } from 'react';

export function useStack(initial = []) {
  const [stack, setStack] = useState(initial);
  return {
    stack,
    push: (item) => setStack(s => [...s, item]),
    pop: () => setStack(s => s.slice(0, -1)),
    peek: stack[stack.length - 1],
    size: stack.length,
  };
}
